import { verifyToken, checkBoardPermission } from "./auth";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/api\/whiteboards\/([^\/]+)\/elements$/);

    if (request.method === "POST" && match) {
      const boardId = match[1];
      const user = await verifyToken(request.headers.get("Authorization"));
      if (!user) return new Response("Unauthorized", { status: 401 });

      // Enforce user write access to the specific whiteboard
      const canEdit = await checkBoardPermission(env.DB, user.id, boardId, "write");
      if (!canEdit) {
        return new Response("Forbidden: No edit rights for this whiteboard", { status: 403 });
      }

      const id = env.WHITEBOARD_DO.idFromName(boardId);
      const stub = env.WHITEBOARD_DO.get(id);

      return stub.fetch(request);
    }

    return new Response("Not Found", { status: 404 });
  }
};

export class WhiteboardDO {
  constructor(state, env) {
    this.state = state;
  }

  async fetch(request) {
    const element = await request.json();
    const elements = (await this.state.storage.get("elements")) || [];
    elements.push(element);
    await this.state.storage.put("elements", elements);

    return new Response(JSON.stringify({ status: "element_added", count: elements.length }), {
      headers: { "Content-Type": "application/json" }
    });
  }
}
